#include <iostream>

int main() {
    int i = 0;
    int j = 0;
    if (!(std::cin >> i >> j)) return 0;

    int* p = &i;
    int* q = &j;

    // Manipulating values via dereference operator *
    *q = 5;
    i++;
    (*q)++;
    *p = (*q) * 2 + 1;

    std::cout << "i=" << i << " j=" << j << " *p=" << *p << " *q=" << *q << "\n";
    return 0;
}

#include <iostream>

int main() {
    int val = 0;
    if (!(std::cin >> val)) return 0;

    int* p = &val;
    int* q = p;
    int* r = q;

    // Using multiple pointers pointing to the same variable
    *p = (*q) * (*q) + 2 * (*r) + 1;
    std::cout << "val=" << val << "\n";

    // Demonstrating pointer arithmetic scaling on an array
    int arr[5] = {10, 20, 30, 40, 50};
    int* ptr = arr; // points to arr[0]

    std::cout << "ptr[0]=" << *ptr
              << " ptr+2=" << *(ptr + 2)
              << " ptr+4=" << *(ptr + 4) << "\n";
    return 0;
}
